function ProductPreview({product}:{product:Product}){return <div className="preview-stage"><div className="preview-phone"><p className="preview-brand">初见 · FRESH</p><small>{product.kind}</small><h3>{product.name}</h3><p>{product.summary}</p><div className="preview-price"><b>{product.price}</b><span>{product.seedPrice}</span></div><ul>{product.contents.map(x=><li key={x}>✓ {x}</li>)}</ul><div className="preview-note">有效期：{product.validity}<br/>权益将在{product.delivery}</div><button>确认购买</button></div><aside><p className="admin-eyebrow">PREVIEW CHECK</p><h3>发布前预览</h3><ul><li>名称与说明是否面向用户表达</li><li>价格和种子条件是否清晰</li><li>权益次数与有效期是否一致</li><li>不展示内部版本号与状态枚举</li></ul></aside></div>}
function Delivery({product}:{product:Product}){return <><div className="config-card"><b>交付内容</b><p>{product.contents[0]}</p><span>完成支付或权益核销后即时发放</span></div><div className="form-grid"><Field label="使用次数" value="1 次"/><Field label="核销方式" value="用户发起服务时自动核销"/><Field label="失败处理" value="权益不扣减，可安全重试"/><Field label="记录保留" value="长期保留在用户问事记录"/></div></>}
function Bundle({product}:{product:Product}){return <><div className="bundle-list">{product.contents.map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b><label>发放方式<select defaultValue={i===0?"一次性发放":"随会员生效"}><option>一次性发放</option><option>随会员生效</option><option>每周期刷新</option></select></label><button>移除</button></div>)}</div><button className="admin-secondary">＋ 添加单次产品或服务包</button><div className="risk-note">组合发布后会生成权益快照。组成项未来修改，不会反向影响已购买用户。</div></>}
function Pricing({product}:{product:Product}){return <><div className="form-grid"><Field label="标准售价" value={product.price.replace("¥ ","")} suffix="元"/><Field label="会员专属价" value={product.kind==="会员计划"?"不适用":"5.90"} suffix="元"/><Field label="活动价格" value="未启用"/><Field label="价格生效时间" value="发布后立即生效"/></div><h4>智慧种子解锁价格</h4><div className="seed-rule"><label><input type="checkbox" defaultChecked/> 启用智慧种子解锁价</label><Field label="所需智慧种子" value={product.kind==="会员计划"?"160":"80"} suffix="颗"/><Field label="解锁后价格" value={product.kind==="会员计划"?"179.00":"49.90"} suffix="元"/><Field label="种子处理方式" value="支付前预占，成功后扣除"/></div><div className="quote-example"><b>报价模拟</b><span>普通用户：{product.price}</span><span>满足种子条件：{product.seedPrice}</span><button>更换模拟用户</button></div></>}
function Versions({product}:{product:Product}){return <div className="version-list"><div><Tag value={product.status}/><b>{product.version} · 当前版本</b><span>Fred · 今天 10:18</span><button>查看差异</button></div><div><Tag value="已归档"/><b>V2 · 上一个版本</b><span>jiucongtian · 8 月 30 日 18:42</span><button>查看快照</button></div><div><Tag value="已归档"/><b>V1 · 首次发布</b><span>Fred · 8 月 26 日 11:05</span><button>查看快照</button></div></div>}
function NewProduct({close,created}:{close:()=>void;created:()=>Promise<void>}){const [kind,setKind]=useState<"SINGLE"|"PACKAGE">("SINGLE"),[code,setCode]=useState(""),[name,setName]=useState(""),[serviceType,setServiceType]=useState("CARD_READING"),[busy,setBusy]=useState(false),[error,setError]=useState("");const effectiveService=serviceType,initialSpec={[effectiveService]:1};const submit=async()=>{const missing:string[]=[];if(code.trim().length<3)missing.push("商品编号至少填写 3 个字符");if(name.trim().length<2)missing.push("用户端名称至少填写 2 个字");if(missing.length){setError(`暂时无法创建：${missing.join("；")}`);return}setBusy(true);setError("");try{await operationsFetch("/products",{method:"POST",body:JSON.stringify({code:code.trim().toLowerCase(),serviceType:effectiveService,offeringKind:kind,displayName:name.trim(),description:`${name.trim()}的用户端说明`,amountMinor:0,validityDays:null,offeringStatus:"DRAFT",entitlementSpec:initialSpec,promotion:{enabled:false,minimumSeedBalance:0,reservedSeedQuantity:1,activityAmountMinor:0}})});await created()}catch(e){setError(e instanceof Error?e.message:"创建失败")}finally{setBusy(false)}};return <div className="admin-overlay"><section className="admin-modal account-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">NEW PRODUCT</p><h2>创建商品草稿</h2><label>商品类型<select value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="SINGLE">单次产品</option><option value="PACKAGE">服务包</option></select></label><label>商品编号<input aria-invalid={Boolean(error)&&code.trim().length<3} value={code} onChange={e=>setCode(e.target.value.replace(/[^a-zA-Z0-9-_]/g,""))} placeholder="例如：card-reading-10"/></label><label>用户端名称<input aria-invalid={Boolean(error)&&name.trim().length<2} value={name} onChange={e=>setName(e.target.value)} placeholder="请输入用户能理解的名称"/></label><div className="success-note">会员计划固定为微光、清和、自在三类；如需调整，请在商品列表中配置已有计划。</div><label>主要服务类型<select value={serviceType} onChange={e=>setServiceType(e.target.value)}><option value="CARD_READING">抽卡问事</option><option value="DAILY_ENERGY">今日能量</option><option value="RELATIONSHIP_READING">关系疗愈</option><option value="OFFLINE_SERVICE">线下服务</option></select></label>{error&&<div className="risk-note" role="alert">{error}</div>}<div className="modal-actions"><button className="admin-secondary" onClick={close}>取消</button><button className="admin-primary" disabled={busy} onClick={()=>void submit()}>{busy?"创建中…":"创建并继续配置"}</button></div></section></div>}
function Field({label,value,disabled,suffix}:{label:string;value:string;disabled?:boolean;suffix?:string}){return <label className="config-field">{label}<span><input defaultValue={value} disabled={disabled}/>{suffix&&<i>{suffix}</i>}</span></label>}
function Orders({data,tell}:{data:Order[];tell:(s:string)=>void}){const [rows,setRows]=useState(data),[status,setStatus]=useState(""),[query,setQuery]=useState(""),[appliedQuery,setAppliedQuery]=useState(""),[page,setPage]=useState(1),[total,setTotal]=useState(0),[totalPages,setTotalPages]=useState(1),[loading,setLoading]=useState(false),[selected,setSelected]=useState<Order|null>(null);useEffect(()=>{let active=true;setLoading(true);operationsFetch<{data:any[];pagination:{total:number;totalPages:number}}>(`/orders?page=${page}&pageSize=20&status=${encodeURIComponent(status)}&q=${encodeURIComponent(appliedQuery)}`).then(x=>{if(!active)return;setRows(x.data.map(o=>({id:o.order_number||o.id,user:o.user,item:o.display_name||"未命名商品",amount:`¥ ${(Number(o.amount_minor||0)/100).toFixed(2)}`,pay:cn(o.status),grant:cn(o.fulfillment_status)})));setTotal(x.pagination.total);setTotalPages(x.pagination.totalPages)}).catch(e=>tell(e instanceof Error?e.message:"订单加载失败")).finally(()=>active&&setLoading(false));return()=>{active=false}},[page,status,appliedQuery]);const search=()=>{setPage(1);setAppliedQuery(query.trim())};return <section className="admin-page"><div className="admin-toolbar"><label className="admin-search">⌕<input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&search()} placeholder="输入订单号、脱敏手机号或请求编号"/></label><button className="admin-primary" onClick={search} disabled={loading}>{loading?"查询中…":"查询订单"}</button><select value={status} onChange={e=>{setPage(1);setStatus(e.target.value)}}><option value="">全部状态</option><option value="PENDING_PAYMENT">待支付</option><option value="PAYMENT_PROCESSING">支付确认中</option><option value="FULFILLED">已到账</option><option value="EXCEPTION">到账异常</option><option value="REFUNDED">已退款</option></select></div><article className="admin-panel admin-table-panel"><Head en="ORDER & DELIVERY" title={`订单与权益到账 · 共 ${total} 笔`}/>{rows.length?<><table><thead><tr><th>订单</th><th>用户</th><th>商品</th><th>金额</th><th>支付</th><th>权益</th><th/></tr></thead><tbody>{rows.map(o=><tr key={o.id}><td><b>{o.id}</b></td><td><UserLabel user={o.user}/></td><td>{o.item}</td><td>{o.amount}</td><td>{o.pay}</td><td><Tag value={o.grant}/></td><td><button className="admin-link" onClick={()=>setSelected(o)}>诊断 →</button></td></tr>)}</tbody></table><Pagination page={page} total={total} pageSize={20} totalPages={totalPages} change={setPage}/></>:<div className="empty-state"><b>{loading?"正在加载订单":"暂无匹配订单"}</b><span>可调整查询条件后重试。</span></div>}</article>{selected&&<OrderDiagnostic order={selected} close={()=>setSelected(null)} tell={tell}/>}</section>}
function OrderDiagnostic({order,close,tell:_tell}:{order:Order;close:()=>void;tell:(s:string)=>void}){return <div className="admin-overlay" onClick={close}><aside className="admin-drawer order-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">ORDER DETAIL</p><h2>订单详情</h2><p className="drawer-phone">{order.id}</p><div className="order-overview"><Info a="用户" b={`${order.user.nickname} · ${order.user.phone_masked}`}/><Info a="商品" b={order.item}/><Info a="实付" b={order.amount}/><Info a="支付状态" b={order.pay}/><Info a="权益到账" b={order.grant}/></div><div className="success-note">这里只展示服务端已有的真实订单和到账状态；退款、补发等高风险操作在后端能力和审核链路接通前不提供假入口。</div></aside></div>}
function UserPanel({user,close,grant}:{user:User;close:()=>void;grant:()=>void}){const [tab,setTab]=useState("概览");return <div className="admin-overlay" onClick={close}><aside className="admin-drawer user-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">USER PROFILE · ADMIN-USER-02</p><h2>{user.name}</h2><p className="drawer-phone">{user.phone} · 用户编号 U20260828031</p><div className="drawer-summary"><Info a="档案状态" b={user.profile}/><Info a="智慧种子" b={`${user.seed} 颗`}/><Info a="会员计划" b={user.member}/><Info a="账号状态" b={user.status}/></div><div className="mini-tabs">{["概览","权益","订单","服务记录","客服记录"].map(x=><button className={tab===x?"is-active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==="概览"&&<><h3>最近状态</h3><ul className="timeline"><li><b>今日能量生成成功</b><span>今天 08:12</span></li><li><b>会员权益完成刷新</b><span>9 月 1 日 00:03</span></li><li><b>完成生命智慧档案</b><span>8 月 28 日 19:45</span></li></ul></>}{tab==="权益"&&<DetailList items={[["智慧种子",`${user.seed} 颗 · 正常`],["会员",`${user.member} · 2026-10-01 到期`],["服务包","抽卡问事 8/10 次"]]}/>} {tab==="订单"&&<DetailList items={[["FR202609020018","清和计划 · ¥199.00 · 支付成功"],["FR202608280075","抽卡问事 · 1 次权益 · 已完成"]]}/>} {tab==="服务记录"&&<DetailList items={[["今日能量","今天 08:12 · 生成成功"],["抽卡问事","9 月 1 日 21:42 · 报告已完成"]]}/>} {tab==="客服记录"&&<DetailList items={[["权益不到账咨询","9 月 1 日 · 已解决"],["注册启程礼补发","8 月 28 日 · 操作人 Fred"]]}/>}<button className="admin-primary full" onClick={grant}>为该用户发放权益</button></aside></div>}
function UserPanelLive({user,close}:{user:User;close:()=>void}){const [detail,setDetail]=useState<any|null>(null),[error,setError]=useState("");useEffect(()=>{if(user.id)operationsFetch<{data:any}>(`/users/${user.id}`).then(x=>setDetail(x.data)).catch(e=>setError(e.message))},[user.id]);const items=(detail?.entitlements||[]).map((x:any)=>[`${cn(x.service_type)} · ${String(x.id).slice(0,8)}`,`${x.available_quantity}/${x.total_quantity} · ${cn(x.status)}`]);const seedItems=(detail?.seeds||[]).map((x:any)=>[`智慧种子 · ${String(x.id).slice(0,8)}`,`${x.available_quantity}/${x.total_quantity} · ${cn(x.status)}`]);const orderItems=(detail?.orders||[]).map((x:any)=>[x.order_number||String(x.id).slice(0,8),`¥ ${(Number(x.amount_minor||0)/100).toFixed(2)} · ${cn(x.status)}`]);return <div className="admin-overlay" onClick={close}><aside className="admin-drawer user-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">USER PROFILE · ADMIN-USER-02</p><h2>{user.name}</h2><p className="drawer-phone">账户编号 {user.code}</p><details className="technical-id"><summary>技术排查信息</summary><code>{user.id}</code></details><div className="drawer-summary"><Info a="账号状态" b={user.status}/><Info a="智慧种子" b={`${user.seed} 颗`}/><Info a="订单数" b={detail?String(detail.orders?.length||0):"加载中"}/><Info a="服务权益" b={detail?String(detail.entitlements?.length||0):"加载中"}/></div>{error&&<div className="risk-note">{error}</div>}<h3>智慧种子与服务权益</h3><DetailList items={[...seedItems,...items]}/><h3>订单记录</h3><DetailList items={orderItems}/></aside></div>}
function DetailList({items}:{items:string[][]}){return <div className="detail-list">{items.length?items.map((x,i)=><div key={`${x[0]}-${i}`}><b>{x[0]}</b><span>{x[1]}</span></div>):<p className="empty-detail">暂无记录</p>}</div>}
function Grant({close,done}:{close:()=>void;done:(message:string)=>Promise<void>}){const [kind,setKind]=useState<"SEED"|"OFFERING">("SEED"),[phone,setPhone]=useState(""),[quantity,setQuantity]=useState("18"),[validity,setValidity]=useState(""),[offeringId,setOfferingId]=useState(""),[reason,setReason]=useState(""),[confirmed,setConfirmed]=useState(false),[options,setOptions]=useState<any[]>([]),[error,setError]=useState(""),[busy,setBusy]=useState(false);useEffect(()=>{operationsFetch<{data:{offerings:any[]}}>("/benefits/grant-options").then(x=>setOptions(x.data.offerings)).catch(e=>setError(e instanceof Error?e.message:"可赠送商品加载失败"))},[]);const submit=async()=>{setBusy(true);setError("");try{await operationsFetch("/benefits/grant-requests",{method:"POST",body:JSON.stringify({phone,kind,seedQuantity:kind==="SEED"?Number(quantity):undefined,validityDays:validity?Number(validity):null,offeringVersionId:kind==="OFFERING"?offeringId:undefined,reason})});await done("赠送申请已提交，等待审核后到账")}catch(e){setError(e instanceof Error?e.message:"提交失败")}finally{setBusy(false)}};return <div className="admin-overlay"><section className="admin-modal grant-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">MANUAL GRANT · ADMIN-BENEFIT-05</p><h2>按手机号赠送权益</h2><p className="section-help">请确认手机号和赠送内容；审核通过后，已注册用户立即到账，未注册用户在该手机号注册时自动领取。</p><label>用户手机号<input value={phone} onChange={e=>setPhone(e.target.value.replace(/\D/g,"").slice(0,11))} placeholder="输入 11 位手机号"/></label><label>赠送类型<select value={kind} onChange={e=>{setKind(e.target.value as "SEED"|"OFFERING");setOfferingId("")}}><option value="SEED">智慧种子</option><option value="OFFERING">会员计划、服务包或单次产品</option></select></label>{kind==="SEED"?<div className="form-row"><label>发放数量<input type="number" min="1" value={quantity} onChange={e=>setQuantity(e.target.value)}/><small>单位：颗</small></label><label>有效期<input type="number" min="1" value={validity} onChange={e=>setValidity(e.target.value)} placeholder="留空为长期有效"/><small>单位：天</small></label></div>:<><label>选择已发布商品<select value={offeringId} onChange={e=>setOfferingId(e.target.value)}><option value="">请选择商品</option>{options.map(x=><option key={x.id} value={x.id}>{x.display_name} · V{x.version}（{x.offering_kind==="MEMBERSHIP"?"会员计划":x.offering_kind==="PACKAGE"?"服务包":"单次产品"}）</option>)}</select></label><label>有效期覆盖（可选）<input type="number" min="1" value={validity} onChange={e=>setValidity(e.target.value)} placeholder="留空沿用商品规则"/><small>会员计划沿用计划周期；服务包和单次产品默认沿用商品有效期。</small></label></>}<label>赠送原因<textarea value={reason} onChange={e=>setReason(e.target.value)} placeholder="例如：线下活动权益赠送、异常补偿"/></label><label className="confirm-check"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> 我已核对手机号、权益内容、数量和有效期</label>{error&&<div className="risk-note">{error}</div>}<div className="modal-actions"><button className="admin-secondary" onClick={close}>取消</button><button className="admin-primary" disabled={busy||!confirmed||phone.length!==11||reason.trim().length<3||(kind==="SEED"&&Number(quantity)<1)||(kind==="OFFERING"&&!offeringId)} onClick={()=>void submit()}>{busy?"提交中…":"提交审核"}</button></div></section></div>}
function Approvals({tell}:{tell:(s:string)=>void}){const [data,setData]=useState<any[]>([]),[busy,setBusy]=useState("");const load=()=>operationsFetch<{data:any[]}>("/action-requests").then(x=>setData(x.data));useEffect(()=>{void load()},[]);const review=async(id:string,decision:"approve"|"reject")=>{setBusy(id);try{await operationsFetch(`/action-requests/${id}/${decision}`,{method:"POST",body:JSON.stringify({note:decision==="approve"?"核对无误，同意执行":"资料不足，暂不执行"})});tell(decision==="approve"?"审核通过并已执行":"申请已驳回");await load()}catch(e){tell(e instanceof Error?e.message:"审核失败")}finally{setBusy("")}};const kind=(value:string)=>({SINGLE:"单次产品",PACKAGE:"服务包",MEMBERSHIP:"会员计划"})[value]||"商品",grantLabel=(p:any)=>p?.kind==="SEED"?`${p.seedQuantity||0} 颗智慧种子 · ${p.phoneMasked||"未提供手机号"}`:`商品权益 · ${p?.offeringVersionId?String(p.offeringVersionId).slice(0,8):"未选择商品"}`;return <section className="admin-page"><div className="success-note">普通账号遵循创建与审批分离；超级管理员可在人员不足时审批自己的申请，所有操作都会写入审计记录。执行失败的申请可修复原因后重试。</div><article className="admin-panel admin-table-panel"><Head en="APPROVAL CENTER" title={`审核申请 · ${data.length}`}/>{data.length?<table><thead><tr><th>申请内容</th><th>修改内容</th><th>申请原因</th><th>提交人</th><th>提交时间</th><th>状态</th><th/></tr></thead><tbody>{data.map(x=><tr key={x.id}><td><b>{x.action_type==="PRODUCT_CHANGE"?(x.payload?.displayName||x.payload?.code||"未命名商品"):cn(x.action_type)}</b><small>{x.action_type==="PRODUCT_CHANGE"?`${x.payload?.code||"—"} · ${kind(x.payload?.offeringKind)}`:x.action_type==="MANUAL_BENEFIT_GRANT"?grantLabel(x.payload):String(x.id).slice(0,8)}</small></td><td><span className="change-list">{x.action_type==="MANUAL_BENEFIT_GRANT"?<><small>• 权益：{grantLabel(x.payload)}</small><small>• 有效期：{x.payload?.validityDays?`${x.payload.validityDays} 天`:"按商品规则或长期有效"}</small></>:Array.isArray(x.payload?.changes)?x.payload.changes.map((change:string)=><small key={change}>• {change}</small>):<small>历史申请未记录差异</small>}</span></td><td>{x.reason}</td><td>{x.submitted_by}</td><td>{new Date(x.created_at).toLocaleString("zh-CN")}</td><td><Tag value={cn(x.status)}/></td><td>{["PENDING","FAILED"].includes(x.status)&&<><button disabled={busy===x.id} className="admin-link" onClick={()=>void review(x.id,"approve")}>{x.status==="FAILED"?"重新执行":"通过并执行"}</button> <button disabled={busy===x.id} className="admin-link" onClick={()=>void review(x.id,"reject")}>驳回</button></>}</td></tr>)}</tbody></table>:<div className="empty-state"><b>暂无审核申请</b><span>人工权益调整和商品变更会在这里留下审批记录。</span></div>}</article></section>}
function System({tell,operator}:{tell:(s:string)=>void;operator:CurrentOperator|null}){const superAdmin=Boolean(operator?.roles?.some(x=>x.code==="SUPER_ADMIN")),tabs=superAdmin?["账号与角色","权限矩阵","我的资料"]:["我的资料"], [tab,setTab]=useState(tabs[0]);return <section className="admin-page"><div className="admin-tabbar">{tabs.map(x=><button className={tab===x?"is-active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==="账号与角色"&&<AccountManager tell={tell}/>} {tab==="权限矩阵"&&<PermissionMatrix/>} {tab==="我的资料"&&<MyProfile operator={operator} tell={tell}/>}</section>}
function AccountManager({tell}:{tell:(s:string)=>void}){const [accounts,setAccounts]=useState<OperationAccount[]>([]),[roles,setRoles]=useState<OperationRole[]>([]),[editing,setEditing]=useState<OperationAccount|null|"new">(null),[initialPassword,setInitialPassword]=useState("");const load=async()=>{const [a,r]=await Promise.all([operationsFetch<{data:OperationAccount[]}>("/accounts"),operationsFetch<{data:OperationRole[]}>("/meta/operation-roles")]);setAccounts(a.data);setRoles(r.data)};useEffect(()=>{void load()},[]);const reset=async(a:OperationAccount)=>{if(!window.confirm(`确认重置“${a.nickname}”的登录密码？旧密码将立即失效。`))return;try{const result=await operationsFetch<{data:{initialPassword:string}}>(`/accounts/${a.id}/reset-password`,{method:"POST"});setEditing(a);setInitialPassword(result.data.initialPassword);await load()}catch(e){tell(e instanceof Error?e.message:"密码重置失败")}};const remove=async(a:OperationAccount)=>{if(!window.confirm(`确认删除运营账号“${a.nickname}（${a.phone}）”？删除后不可登录。`))return;try{await operationsFetch(`/accounts/${a.id}`,{method:"DELETE"});tell("运营账号已删除");await load()}catch(e){tell(e instanceof Error?e.message:"账号删除失败")}};return <><article className="admin-panel admin-table-panel"><div className="panel-title-action"><Head en="ACCOUNT & ROLE" title={`后台账号与角色 · ${accounts.length}`}/><button className="admin-primary" onClick={()=>{setInitialPassword("");setEditing("new")}}>＋ 创建运营账号</button></div><div className="success-note">手机号是运营账号的唯一登录标识，创建后不可修改。超级管理员可配置角色、停用、重置密码或删除普通运营账号。</div><table><thead><tr><th>账号</th><th>已分配角色</th><th>创建时间</th><th>密码状态</th><th>状态</th><th>管理</th></tr></thead><tbody>{accounts.map(a=><tr key={a.id}><td><b>{a.nickname}</b><small>{a.phone}</small></td><td>{a.roles.map(r=><span className="role-chip" key={r.code}>{r.name}</span>)}</td><td>{new Date(a.created_at).toLocaleDateString("zh-CN")}</td><td>{a.password_changed_at?"已自行修改":"使用初始密码"}</td><td><Tag value={a.status==="ACTIVE"?"正常":"已停用"}/></td><td><button className="admin-link" onClick={()=>{setInitialPassword("");setEditing(a)}}>配置</button> <button className="admin-link" onClick={()=>void reset(a)}>重置密码</button> <button className="admin-link danger-link" onClick={()=>void remove(a)}>删除</button></td></tr>)}</tbody></table>{accounts.length===0&&<div className="empty-state"><b>暂无手机号运营账号</b><span>可以创建第一位运营人员。</span></div>}</article>{editing&&<AccountEditor account={editing==="new"?null:editing} roles={roles} initialPassword={initialPassword} close={()=>setEditing(null)} saved={async password=>{setInitialPassword(password||"");if(!password){setEditing(null);tell("账号权限已更新")}await load()}}/>}</>}
function AccountEditor({account,roles,initialPassword,close,saved}:{account:OperationAccount|null;roles:OperationRole[];initialPassword:string;close:()=>void;saved:(password?:string)=>Promise<void>}){const [phone,setPhone]=useState(account?.phone||""),[nickname,setNickname]=useState(account?.nickname||""),[selected,setSelected]=useState<string[]>(account?.roles.map(x=>x.code)||["PRODUCT_OPERATOR"]),[status,setStatus]=useState(account?.status||"ACTIVE"),[busy,setBusy]=useState(false),[error,setError]=useState("");const toggle=(code:string)=>setSelected(x=>x.includes(code)?x.filter(y=>y!==code):[...x,code]);const submit=async()=>{setBusy(true);setError("");try{if(account){await operationsFetch(`/accounts/${account.id}/roles`,{method:"PATCH",body:JSON.stringify({roles:selected,status})});await saved()}else{const result=await operationsFetch<{data:{initialPassword:string}}>("/accounts",{method:"POST",body:JSON.stringify({phone,nickname,roles:selected})});await saved(result.data.initialPassword)}}catch(e){setError(e instanceof Error?e.message:"保存失败")}finally{setBusy(false)}};return <div className="admin-overlay"><section className="admin-modal account-modal"><button className="admin-close" onClick={close}>×</button><p className="admin-eyebrow">{account?"ACCOUNT MANAGEMENT":"CREATE OPERATOR"}</p><h2>{account?"管理运营账号":"创建运营账号"}</h2>{initialPassword?<div className="initial-password"><b>{account?"密码已重置":"账号创建成功"}</b><p>新初始密码仅展示这一次，请安全交给账号本人。</p><code>{initialPassword}</code><button className="admin-primary full" onClick={close}>我已保存，完成</button></div>:<><label>登录手机号<input value={phone} disabled={Boolean(account)} onChange={e=>setPhone(e.target.value.replace(/\D/g,"").slice(0,11))} placeholder="11 位手机号"/></label><label>昵称<input value={nickname} disabled={Boolean(account)} onChange={e=>setNickname(e.target.value)} placeholder="例如：客服小青"/></label><fieldset className="role-options"><legend>分配角色</legend>{roles.map(role=><label key={role.code}><input type="checkbox" checked={selected.includes(role.code)} onChange={()=>toggle(role.code)}/><span>{role.name}</span></label>)}</fieldset>{account&&<label>账号状态<select value={status} onChange={e=>setStatus(e.target.value)}><option value="ACTIVE">正常</option><option value="DISABLED">停用</option></select></label>}{error&&<div className="risk-note">{error}</div>}<div className="modal-actions"><button className="admin-secondary" onClick={close}>取消</button><button className="admin-primary" disabled={busy||selected.length===0||(!account&&(phone.length!==11||nickname.length<2))} onClick={()=>void submit()}>{busy?"保存中…":account?"保存配置":"创建账号"}</button></div></>}</section></div>}
function MyProfile({operator,tell}:{operator:CurrentOperator|null;tell:(s:string)=>void}){const [nickname,setNickname]=useState(operator?.nickname||""),[currentPassword,setCurrentPassword]=useState(""),[newPassword,setNewPassword]=useState("");if(operator?.bootstrap)return <article className="admin-panel placeholder-panel"><span>系统引导管理员</span><h2>{operator.nickname}</h2><p>该账号由测试服务器安全配置维护。手机号运营账号可在这里自行修改昵称与密码。</p></article>;const save=async()=>{try{await operationsFetch('/me',{method:'PATCH',body:JSON.stringify({nickname,currentPassword:currentPassword||undefined,newPassword:newPassword||undefined})});setCurrentPassword("");setNewPassword("");tell("个人资料已更新")}catch(e){tell(e instanceof Error?e.message:"更新失败")}};return <article className="admin-panel profile-settings"><Head en="MY ACCOUNT" title="我的资料"/><p>登录手机号：<b>{operator?.phone}</b>（唯一标识，不可修改）</p><label>昵称<input value={nickname} onChange={e=>setNickname(e.target.value)}/></label><label>当前密码<input type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/></label><label>新密码<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="至少 8 位；不修改可留空"/></label><button className="admin-primary" onClick={()=>void save()}>保存我的资料</button></article>}
function PermissionMatrix(){const rows=[["超级管理员","读写","读写","读写","读写","正式发布"],["产品运营","只读","读写","只读","只读","提交审核"],["用户运营","读写","只读","读写","只读","—"],["客服","读写","只读","提交申请","只读","—"],["财务","只读","只读","只读","读写","—"],["技术管理员","只读","只读","只读","只读","技术配置"]];return <article className="admin-panel permission-panel"><Head en="RBAC + DATA SCOPE" title="角色权限矩阵"/><div className="permission-grid"><b>角色</b><b>用户</b><b>商品</b><b>权益</b><b>订单</b><b>发布</b>{rows.map(r=><div className="permission-row" key={r[0]}>{r.map((x,i)=>i===0?<strong key={x}>{x}</strong>:<span key={`${r[0]}-${i}`}>{x}</span>)}</div>)}</div><div className="risk-note">一个账号可拥有多个角色，最终权限取有效角色并集。账号本人不能修改自己的权限；正式发布和高风险权益操作仍受审批限制。</div></article>}
function Audit(){const [data,setData]=useState<any[]>([]),[selected,setSelected]=useState<any|null>(null);useEffect(()=>{operationsFetch<{data:any[]}>("/audit").then(x=>setData(x.data)).catch(()=>setData([]))},[]);return <section className="admin-page"><article className="admin-panel admin-table-panel"><Head en="AUDIT LOG" title={`操作审计 · ${data.length}`}/>{data.length?<table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>业务对象</th><th>详情</th></tr></thead><tbody>{data.map(x=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString("zh-CN")}</td><td><UserLabel user={x.actor}/></td><td>{cn(x.action)}</td><td>{cn(x.resource_type)} · {String(x.resource_id||"").slice(0,8)}</td><td><button className="admin-link" onClick={()=>setSelected(x)}>查看记录</button></td></tr>)}</tbody></table>:<div className="empty-state"><b>暂无审计记录</b><span>所有高风险操作都必须可追踪。</span></div>}</article>{selected&&<div className="admin-overlay" onClick={()=>setSelected(null)}><aside className="admin-drawer audit-drawer" onClick={e=>e.stopPropagation()}><button className="admin-close" onClick={()=>setSelected(null)}>×</button><p className="admin-eyebrow">AUDIT DETAIL</p><h2>操作记录详情</h2><div className="drawer-summary"><Info a="操作" b={cn(selected.action)}/><Info a="时间" b={new Date(selected.created_at).toLocaleString("zh-CN")}/><Info a="操作人" b={`${selected.actor?.nickname||"未设置昵称"} · ${selected.actor?.phone_masked||"未绑定手机号"}`}/><Info a="业务对象" b={`${cn(selected.resource_type)} · ${selected.resource_id||"—"}`}/></div><h3>操作内容</h3><pre className="audit-metadata">{JSON.stringify(selected.metadata||{},null,2)}</pre></aside></div>}</section>}
function Pagination({page,total,pageSize,totalPages,change}:{page?:number;total?:number;pageSize?:number;totalPages?:number;change?:(page:number)=>void}){if(!page||total===undefined||!pageSize||!totalPages||!change)return null;const pages=Array.from({length:Math.min(totalPages,5)},(_,i)=>Math.max(1,Math.min(totalPages-4,page-2))+i).filter((x,i,a)=>x>=1&&x<=totalPages&&a.indexOf(x)===i);return <div className="pagination"><span>共 {total} 条 · 每页 {pageSize} 条</span><button disabled={page<=1} onClick={()=>change(page-1)}>上一页</button>{pages.map(x=><button key={x} className={page===x?"is-active":""} onClick={()=>change(x)}>{x}</button>)}<button disabled={page>=totalPages} onClick={()=>change(page+1)}>下一页</button></div>}
function Toolbar({placeholder,button}:{placeholder:string;button:string}){return <div className="admin-toolbar"><label className="admin-search">⌕<input placeholder={placeholder}/></label><button className="admin-primary">{button}</button><span className="admin-hint">默认隐藏敏感信息，完整手机号仅在授权后显示</span></div>}
function Tabs({items}:{items:string[]}){return <div className="admin-tabbar">{items.map((x,i)=><button className={i===0?"is-active":""} key={x}>{x}</button>)}</div>}
function Head({en,title}:{en:string;title:string}){return <div className="admin-panel-head"><div><p className="admin-eyebrow">{en}</p><h2>{title}</h2></div></div>}
function Task({tone,title,note,action,click}:{tone:string;title:string;note:string;action:string;click:()=>void}){return <div className="admin-task"><span className={`admin-dot is-${tone}`}/><div><strong>{title}</strong><p>{note}</p></div><button onClick={click}>{action}</button></div>}
function Stat({a,b,c}:{a:string;b:string;c:string}){return <article className="admin-stat"><p>{a}</p><strong>{b}</strong><small>{c}</small></article>}
function Tag({value}:{value:string}){const cls=/异常/.test(value)?"danger":/待|预占|未发放/.test(value)?"warn":"";return <em className={`tag ${cls}`}>{value}</em>}
function Info({a,b}:{a:string;b:string}){return <div><small>{a}</small><b>{b}</b></div>}
